mapper.select:
SELECT u.id, u.user_code, u.user_name, u.email, u.phone, u.avatar, u.gender, u.status, u.dept_id, d.dept_name, u.create_time, u.last_login_time FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id WHERE 1=1
AND u.user_code LIKE CONCAT('%', #{query.userCode}, '%')
AND u.user_name LIKE CONCAT('%', #{query.userName}, '%')
AND u.phone LIKE CONCAT('%', #{query.phone}, '%')
AND u.status = #{query.status}
AND u.create_time >= #{query.createTimeStart}
AND u.create_time <= #{query.createTimeEnd}
ORDER BY u.create_time DESC
